/*
 * A driver family: one LKL instance per family, each owning a disjoint
 * set of #P devices and a disjoint slice of the #P/dma arena.
 *
 * The tables in lkl-tables.c are generated by util/arm64/build_lkl.py
 * from util/arm64/lkl-families.json; keep the struct layout in sync.
 */
typedef struct Family Family;
struct Family {
	char	*name;		/* emmc, usb, ... */
	char	*program;	/* lklemc, lklusb, ... */
	char	*mem;		/* mem= string for the guest */
	unsigned long memsz;	/* same, in bytes */
	char	*devices;	/* comma-separated #P node names */
	char	*dtbname;	/* embedded device tree */
	int	setup;		/* FamEmmc, FamUsb, ... */
};

enum {
	FamNone,
	FamEmmc,
	FamUsb,
};

typedef struct Dtb Dtb;
struct Dtb {
	char	*name;
	uchar	*start;
	uchar	*end;
};

extern Family	lklfamilies[];
extern int	nlklfamilies;
extern Dtb	lkldtbs[];
extern int	nlkldtbs;
